/** 取一格之承注：{ ans, cites:[{t,r,n,j}], level, plain } —— 無則 null */
export function czOf(position, combo) {
  const row = CZ[`${position}|${combo}`];
  if (!row) return null;
  return {
    ans: CZ_ANS[row[0]],
    cites: row[1].map((i) => CZ_CITE[i]),
    level: row[2],
    plain: row[3] || '',
  };
}
